-- Additive notification metadata and reversible dismissal. Existing RLS stays in force.
alter table public.notifications add column if not exists target jsonb;
alter table public.notifications add column if not exists dismissed boolean not null default false;

-- Capture IDs generated by the existing commands without changing their transitions.
create function public.capture_notification_record() returns trigger
language plpgsql set search_path = '' as $$
declare context jsonb := nullif(current_setting('nexus.notification_context',true),'')::jsonb;
begin
  if tg_table_name='tickets' and context->>'type'='createTicket' then
    perform set_config('nexus.notification_context',(context || jsonb_build_object('ticketId',new.id))::text,true);
  elsif tg_table_name='appointments' and context->>'type'='createAppointment' then
    perform set_config('nexus.notification_context',(context || jsonb_build_object('appointmentId',new.id))::text,true);
  end if;
  return new;
end;
$$;
create trigger capture_ticket_notification_id after insert on public.tickets
for each row execute function public.capture_notification_record();
create trigger capture_appointment_notification_id after insert on public.appointments
for each row execute function public.capture_notification_record();

create function public.attach_notification_target() returns trigger
language plpgsql set search_path = '' as $$
declare context jsonb := nullif(current_setting('nexus.notification_context',true),'')::jsonb;
  action text := context->>'type'; kind text; target_id text;
begin
  if action='sendMessage' then kind:='conversation'; target_id:=context->>'ticketId';
  elsif action in ('verifyPayment','pay') then kind:='payment'; target_id:=context->>'paymentId';
  elsif action in ('createAppointment','cancelAppointment','editAppointment','rescheduleAppointment') then
    kind:='appointment'; target_id:=context->>'appointmentId';
  elsif action='reviewDocument' then kind:='document'; target_id:=context->>'documentId';
  elsif action in ('createTicket','acceptTicket','assignTicket','createPayment','deliver','closeTicket') then
    kind:='ticket'; target_id:=context->>'ticketId';
  end if;
  if kind is not null and target_id is not null then
    new.target:=jsonb_build_object('kind',kind,'id',target_id);
  end if;
  return new;
end;
$$;
create trigger notification_record_target before insert on public.notifications
for each row execute function public.attach_notification_target();
revoke execute on function public.capture_notification_record(),public.attach_notification_target() from public,anon,authenticated;

-- Retain the existing public RPC and delegate every non-notification command
-- to its unmodified implementation, including all privacy and business checks.
alter function public.workspace_command(jsonb) rename to workspace_command_v1347;
revoke execute on function public.workspace_command_v1347(jsonb) from public,anon,authenticated;
create function public.workspace_command(command jsonb) returns void
language plpgsql security definer set search_path = '' as $$
declare action text := command->>'type'; note_id uuid; note_ids uuid[];
  previous_context text := current_setting('nexus.notification_context',true);
begin
  if public.current_role() is null then raise exception 'An active account is required.'; end if;
  if action in ('setNotificationRead','dismissNotification') then
    note_id := (command->>'notificationId')::uuid;
    perform 1 from public.notifications where id=note_id and "userId"=auth.uid() for update;
    if not found then raise exception 'Notification not found.'; end if;
    if action='setNotificationRead' then
      if jsonb_typeof(command->'read') is distinct from 'boolean' then raise exception 'Choose a valid notification status.'; end if;
      update public.notifications set read=(command->>'read')::boolean where id=note_id and "userId"=auth.uid();
    else
      if jsonb_typeof(command->'dismissed') is distinct from 'boolean' then raise exception 'Choose a valid notification status.'; end if;
      update public.notifications set dismissed=(command->>'dismissed')::boolean where id=note_id and "userId"=auth.uid();
    end if;
    return;
  elsif action='readNotifications' then
    if command ? 'notificationIds' then
      if jsonb_typeof(command->'notificationIds') is distinct from 'array' then raise exception 'Notification not found.'; end if;
      select array_agg(value::uuid) into note_ids from jsonb_array_elements_text(command->'notificationIds');
      if exists(select 1 from unnest(note_ids) as wanted(id) where not exists (
        select 1 from public.notifications n where n.id=wanted.id and n."userId"=auth.uid()
      )) then raise exception 'Notification not found.'; end if;
      update public.notifications set read=true where "userId"=auth.uid() and not dismissed and id=any(note_ids);
    else
      update public.notifications set read=true where "userId"=auth.uid() and not dismissed;
    end if;
    return;
  end if;
  -- Do not trust client-supplied targets: only validated command record IDs
  -- and the IDs captured from actual inserts become notification metadata.
  perform set_config('nexus.notification_context',jsonb_build_object(
    'type',action,'ticketId',command->'ticketId','paymentId',command->'paymentId',
    'appointmentId',command->'appointmentId','documentId',command->'documentId'
  )::text,true);
  perform public.workspace_command_v1347(command);
  perform set_config('nexus.notification_context',coalesce(previous_context,''),true);
exception when others then
  perform set_config('nexus.notification_context',coalesce(previous_context,''),true);
  raise;
end;
$$;
revoke execute on function public.workspace_command(jsonb) from public,anon;
grant execute on function public.workspace_command(jsonb) to authenticated;
